<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\HomeController; use App\Http\Controllers\ProductController; use App\Http\Controllers\InquiryController;
use App\Http\Controllers\Admin\AuthController as AdminAuth; use App\Http\Controllers\Admin\DashboardController; use App\Http\Controllers\Admin\CategoryController; use App\Http\Controllers\Admin\ProductController as AdminProductController; use App\Http\Controllers\Admin\PageController; use App\Http\Controllers\Admin\InquiryController as AdminInquiryController; use App\Http\Controllers\Admin\SettingsController; use App\Http\Controllers\Admin\MediaController;
Route::get('/',[HomeController::class,'index'])->name('home'); Route::get('/about',[HomeController::class,'about'])->name('about'); Route::get('/contact',[HomeController::class,'contact'])->name('contact');
Route::get('/products',[ProductController::class,'index'])->name('products.index'); Route::get('/products/{product:slug}',[ProductController::class,'show'])->name('products.show');
Route::get('/inquiry',[InquiryController::class,'inquiry'])->name('inquiry'); Route::get('/quote',[InquiryController::class,'quote'])->name('quote'); Route::post('/requests',[InquiryController::class,'store'])->middleware('throttle:10,1')->name('requests.store');
